// PairErrUnreachable says "Can't reach a computer at {address}. Check that both are on the same network and Phone Sync is on."
// in the language the app shows under cx.
//
// Error on the pairing page: nothing answered at the address.
func PairErrUnreachable(cx *core.Scope, address string) string {
	return For(cx).PairErrUnreachable(address)
}

// PairErrUnreachable is the package's PairErrUnreachable in the language of msgs.
func (msgs Messages) PairErrUnreachable(address string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.PairErrUnreachable(address))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].PairErrUnreachable; f != nil {
			return f(address)
		}
		switch lang {
		case "", "en":
			return "Can't reach a computer at " + msgs.arg(address) + ". Check that both are on the same network and Phone Sync is on."
		case "ja":
			return address + " のコンピュータに接続できません。同じネットワークにあり、スマートフォン同期がオンになっているか確認してください。"
		case "ko":
			return address + "의 컴퓨터에 연결할 수 없습니다. 같은 네트워크에 있고 휴대폰 동기화가 켜져 있는지 확인하세요."
		case "zh-Hans":
			return "连不上 " + address + " 的电脑。请确认两者在同一网络，且已打开手机同步。"
		case "zh-Hant":
			return "連不上 " + address + " 的電腦。請確認兩者在同一個網路，且已開啟手機同步。"
		}
	}
}

